&reftitle.returnvalues;

 &return.success; Функция dl дополнительно выдаст ошибку уровня E_WARNING,
 если значение &false; вернулось по следующими причинам:
 механизм загрузки модулей недоступен, загрузка модулей отключена
 установкой значения Off директиве enable_dl в файле &php.ini;
 или невозможно загрузить библиотеку.

  &reftitle.examples;



    Примеры загрузки PHP-модуля функцией dl


<?php

// Пример загрузки модуля на основе ОС…
if (!extension_loaded('sqlite')) {
    if (strtoupper(substr(PHP_OS, 0, 3)) === 'WIN') {
        dl('php_sqlite.dll');
    } else {
        dl('sqlite.so');
    }
}

// …или на основе значения константы PHP_SHLIB_SUFFIX
if (!extension_loaded('sqlite')) {
    $prefix = (PHP_SHLIB_SUFFIX === 'dll') ? 'php_' : '';
    dl($prefix . 'sqlite.' . PHP_SHLIB_SUFFIX);
}
